sp_widget.client_script:
function($scope, spUtil) {
  var c = this;
  // Initialize selected values
  $scope.selected = {
    hall: null,
    dateString: null,
    slot: null,
    remarks: ""
  };

  $scope.loadingSlots = false;
  $scope.bookingInProgress = false;
  $scope.cancelInProgress = false;
  // Select a facility
  $scope.selectHall = function(hall) {
    if (hall.availability_status !== 'available') {
      spUtil.addErrorMessage("This facility is currently closed or under maintenance.");
      return;
    }
    $scope.selected.hall = hall;
    $scope.selected.slot = null;
    if ($scope.selected.dateString) {
      $scope.fetchSlotAvailability();
    }
  };
  // Triggered on Date Input change
  $scope.onDateChange = function() {
    $scope.selected.slot = null;
    if ($scope.selected.hall && $scope.selected.dateString) {
      $scope.fetchSlotAvailability();
    }
  };
  // Fetch slot availability from server based on selected hall and date
  $scope.fetchSlotAvailability = function() {
    $scope.loadingSlots = true;

    // Call server with query parameters
    c.server.get({
      action: 'get_slots',
      sports_hall_id: $scope.selected.hall.sys_id,
      booking_date: $scope.selected.dateString
    }).then(function(response) {
      $scope.data.slots = response.data.slots;
      $scope.loadingSlots = false;
    }, function(error) {
      $scope.loadingSlots = false;
      spUtil.addErrorMessage("Error loading slot availability. Please try again.");
    });
  };
  // Select a specific slot
  $scope.selectSlot = function(slot) {
    if (slot.status === 'unavailable') {
      spUtil.addErrorMessage("This time slot is marked as unavailable.");
      return;
    }
    if (slot.booking_status === 'approved') {
      spUtil.addErrorMessage("This slot is already booked and approved by another student.");
      return;
    }
    if (slot.booking_status === 'pending') {
      spUtil.addErrorMessage("This slot has a pending reservation request.");
      return;
    }
    $scope.selected.slot = slot;
  };
  // Submit booking request
  $scope.submitBooking = function() {
    if (!$scope.selected.hall || !$scope.selected.dateString || !$scope.selected.slot) {
      spUtil.addErrorMessage("Please fill in all booking details.");
      return;
    }

    $scope.bookingInProgress = true;

    c.server.get({
      action: 'submit_booking',
      sports_hall_id: $scope.selected.hall.sys_id,
      booking_date: $scope.selected.dateString,
      time_slot_id: $scope.selected.slot.sys_id,
      remarks: $scope.selected.remarks
    }).then(function(response) {
      $scope.bookingInProgress = false;
      if (response.data.success) {
        spUtil.addInfoMessage("Your booking request has been submitted successfully! Booking Number: " + response.data.booking_number);

        // Reset selections
        $scope.selected.slot = null;
        $scope.selected.remarks = "";

        // Refresh slots view and dashboard
        $scope.fetchSlotAvailability();
        $scope.refreshDashboard();
      } else {
        spUtil.addErrorMessage(response.data.error_message || "Failed to submit booking request.");
      }
    }, function(error) {
      $scope.bookingInProgress = false;
      spUtil.addErrorMessage("An unexpected server error occurred.");
    });
  };
  // Cancel booking request
  $scope.cancelBooking = function(booking) {
    if (confirm("Are you sure you want to cancel this booking (" + booking.number + ")?")) {
      $scope.cancelInProgress = true;

      c.server.get({
        action: 'cancel_booking',
        booking_id: booking.sys_id
      }).then(function(response) {
        $scope.cancelInProgress = false;
        if (response.data.success) {
          spUtil.addInfoMessage("Booking cancelled successfully.");
          $scope.refreshDashboard();
          if ($scope.selected.hall && $scope.selected.dateString) {
            $scope.fetchSlotAvailability();
          }
        } else {
          spUtil.addErrorMessage(response.data.error_message || "Failed to cancel booking.");
        }
      }, function(error) {
        $scope.cancelInProgress = false;
        spUtil.addErrorMessage("An error occurred while cancelling booking.");
      });
    }
  };
  // Refresh user dashboard list
  $scope.refreshDashboard = function() {
    c.server.get({
      action: 'get_dashboard'
    }).then(function(response) {
      $scope.data.myBookings = response.data.myBookings;
    });
  };
  // Set minimum date picker selection to today
  var today = new Date();
  var dd = String(today.getDate()).padStart(2, '0');
  var mm = String(today.getMonth() + 1).padStart(2, '0'); // January is 0!
  var yyyy = today.getFullYear();
  $scope.data.minDate = yyyy + '-' + mm + '-' + dd;
}

sp_widget.css:
/* Sports Hall Booking CSS Styles */
/* Primary Variables and Colors */
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-gradient-start: #1e3a8a;
  --bg-gradient-end: #3b82f6;
  --card-bg: #ffffff;
  --card-border: #e2e8f0;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --available-color: #10b981;
  --booked-color: #ef4444;
  --pending-color: #f59e0b;
  --unavailable-color: #64748b;
  --completed-color: #8b5cf6;
}
.sports-booking-container {
  font-family: 'Outfit', 'Inter', sans-serif;
  color: var(--text-main);
  background-color: #f8fafc;
  min-height: 100vh;
  padding-bottom: 50px;
}
/* Banner Header Styling */
.booking-banner {
  background: linear-gradient(135deg, var(--bg-gradient-start) 0%, var(--bg-gradient-end) 100%);
  color: #ffffff;
  padding: 60px 20px;
  text-align: center;
  position: relative;
  overflow: hidden;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  border-bottom-left-radius: 20px;
  border-bottom-right-radius: 20px;
}
.booking-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 70%);
  animation: rotateBanner 20s linear infinite;
  pointer-events: none;
}
@keyframes rotateBanner {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
.banner-overlay h1 {
  font-size: 38px;
  font-weight: 800;
  margin-bottom: 12px;
  letter-spacing: -0.5px;
  text-shadow: 0 2px 4px rgba(0,0,0,0.2);
}
.banner-overlay p {
  font-size: 16px;
  font-weight: 300;
  max-width: 650px;
  margin: 0 auto;
  opacity: 0.9;
}
/* Content Area layout */
.booking-content {
  margin-top: -30px;
  padding-left: 30px;
  padding-right: 30px;
}
/* Card Styling */
.booking-card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05), 0 2px 4px -1px rgba(0,0,0,0.03);
  margin-bottom: 25px;
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.booking-card:hover {
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -2px rgba(0,0,0,0.05);
}
.sticky-card {
  position: -webkit-sticky;
  position: sticky;
  top: 20px;
  z-index: 10;
}
.card-header-custom {
  background-color: #ffffff;
  border-bottom: 1px solid #f1f5f9;
  padding: 18px 24px;
  display: flex;
  align-items: center;
}
.card-header-custom h2 {
  font-size: 18px;
  font-weight: 700;
  margin: 0;
  color: var(--text-main);
}
.step-num {
  background-color: var(--primary-color);
  color: #ffffff;
  font-size: 14px;
  font-weight: 700;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 12px;
  box-shadow: 0 2px 4px rgba(59, 130, 246, 0.3);
}
.card-body-custom {
  padding: 24px;
}
/* Sports Hall Selection Styles */
.hall-card {
  border: 2px solid var(--card-border);
  border-radius: 10px;
  padding: 16px;
  margin-bottom: 20px;
  cursor: pointer;
  background-color: #ffffff;
  transition: all 0.2s ease-in-out;
  position: relative;
}
.hall-card:hover {
  border-color: var(--primary-color);
  transform: translateY(-2px);
}
.hall-card.selected {
  border-color: var(--primary-color);
  background-color: #f0f7ff;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.1);
}
.hall-card h3 {
  font-size: 16px;
  font-weight: 700;
  margin-top: 5px;
  margin-bottom: 10px;
  color: var(--text-main);
}
.hall-body p {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 6px;
  display: flex;
  align-items: center;
}
.hall-body p i {
  width: 16px;
  margin-right: 8px;
  color: var(--primary-color);
}
.sport-badge {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 20px;
  text-transform: capitalize;
  display: inline-block;
}
/* Sport Types Badges */
.sport-badge.badminton { background-color: #e0f2fe; color: #0369a1; }
.sport-badge.basketball { background-color: #ffedd5; color: #c2410c; }
.sport-badge.volleyball { background-color: #fae8ff; color: #a21caf; }
.sport-badge.cricket { background-color: #f0fdf4; color: #15803d; }
.sport-badge.table_tennis { background-color: #ecfdf5; color: #047857; }
.sport-badge.football { background-color: #fef2f2; color: #b91c1c; }
.sport-badge.tennis { background-color: #fef9c3; color: #a16207; }
.sport-badge.gym { background-color: #f1f5f9; color: #334155; }
.sport-badge.multy_purpose { background-color: #e0e7ff; color: #4338ca; }
.status-indicator-wrapper {
  margin-top: 12px;
  display: flex;
  align-items: center;
}
.status-indicator {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 6px;
  display: inline-block;
}
.status-indicator.available { background-color: var(--available-color); }
.status-indicator.under_maintenance { background-color: var(--pending-color); }
.status-indicator.closed { background-color: var(--booked-color); }
.status-text {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-muted);
}
/* Date Picker Custom */
.date-picker-custom {
  border-radius: 8px;
  border: 1px solid var(--card-border);
  height: 42px;
  font-weight: 500;
}
.date-picker-custom:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}
/* Time Slots Grid Section */
.slots-section {
  margin-top: 25px;
  border-top: 1px solid #f1f5f9;
  padding-top: 20px;
}
.slots-title {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 15px;
  color: var(--text-main);
}
.loading-slots {
  text-align: center;
  padding: 30px;
  color: var(--text-muted);
}
.slot-card {
  border: 1px solid var(--card-border);
  border-radius: 8px;
  padding: 12px;
  text-align: center;
  cursor: pointer;
  background-color: #ffffff;
  margin-bottom: 15px;
  transition: all 0.2s ease;
}
.slot-card:hover {
  border-color: var(--primary-color);
  background-color: #f8fafc;
}
.slot-card.selected {
  border-color: var(--primary-color);
  background-color: #eff6ff;
  box-shadow: 0 0 0 2px var(--primary-color);
}
.slot-card.booked {
  background-color: #fef2f2;
  border-color: #fecaca;
  cursor: not-allowed;
  opacity: 0.8;
}
.slot-card.booked:hover {
  background-color: #fef2f2;
  border-color: #fecaca;
}
.slot-card.unavailable {
  background-color: #f1f5f9;
  border-color: #cbd5e1;
  cursor: not-allowed;
  opacity: 0.6;
}
.slot-time {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-main);
}
.slot-name {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 4px;
}
.slot-status-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 4px;
  margin-top: 8px;
  text-transform: uppercase;
}
.slot-status-badge.available { background-color: #d1fae5; color: #065f46; }
.slot-status-badge.booked,
.slot-status-badge.approved { background-color: #fee2e2; color: #991b1b; }
.slot-status-badge.pending { background-color: #fef3c7; color: #92400e; }
.slot-status-badge.unavailable { background-color: #e2e8f0; color: #475569; }
/* Booking Form Summary Styles */
.form-placeholder {
  text-align: center;
  padding: 40px 10px;
  color: var(--text-muted);
}
.form-placeholder i {
  font-size: 32px;
  color: #94a3b8;
  margin-bottom: 12px;
}
.summary-details {
  background-color: #f8fafc;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 20px;
  border: 1px dashed var(--card-border);
}
.summary-item {
  display: flex;
  justify-content: space-between;
  margin-bottom: 10px;
  font-size: 13px;
}
.summary-item:last-child {
  margin-bottom: 0;
  border-top: 1px solid #e2e8f0;
  padding-top: 8px;
  margin-top: 8px;
}
.summary-label {
  color: var(--text-muted);
  font-weight: 500;
}
.summary-value {
  color: var(--text-main);
  font-weight: 700;
}
.remarks-custom {
  border-radius: 8px;
  border: 1px solid var(--card-border);
  resize: vertical;
  min-height: 80px;
  font-size: 13px;
}
.remarks-custom:focus {
  border-color: var(--primary-color);
}
.btn-book {
  background-color: var(--primary-color);
  border-color: var(--primary-color);
  font-weight: 700;
  padding: 12px;
  border-radius: 8px;
  font-size: 14px;
  box-shadow: 0 4px 6px -1px rgba(59, 130, 246, 0.2);
  transition: all 0.2s ease;
}
.btn-book:hover, .btn-book:focus {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
  transform: translateY(-1px);
}
/* Dashboard Styles */
.dashboard-section {
  margin-top: 20px;
}
.dashboard-header {
  justify-content: space-between;
}
.header-left {
  display: flex;
  align-items: center;
}
.header-left i {
  font-size: 20px;
  color: var(--primary-color);
  margin-right: 10px;
}
.btn-refresh {
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  padding: 6px 12px;
}
.table-custom {
  margin-bottom: 0;
}
.table-custom th {
  background-color: #f8fafc;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  border-bottom-width: 1px !important;
  padding: 12px 16px !important;
}
.table-custom td {
  padding: 14px 16px !important;
  font-size: 13px;
  vertical-align: middle !important;
  border-top-color: #f1f5f9 !important;
}
.remarks-cell {
  max-width: 250px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.status-badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 20px;
  text-transform: capitalize;
  text-align: center;
}
.status-badge.pending { background-color: #fffbeb; color: #d97706; }
.status-badge.approved { background-color: #ecfdf5; color: #059669; }
.status-badge.rejected { background-color: #fef2f2; color: #dc2626; }
.status-badge.cancelled { background-color: #f1f5f9; color: #475569; }
.status-badge.completed { background-color: #f5f3ff; color: #7c3aed; }
.btn-cancel {
  border-radius: 6px;
  font-weight: 600;
  padding: 4px 8px;
}
.empty-dashboard {
  text-align: center;
  padding: 60px 20px;
  color: var(--text-muted);
}
.empty-dashboard i {
  font-size: 42px;
  color: #cbd5e1;
  margin-bottom: 12px;
}

sp_widget.script:
(function() {
  /* Server Script for Sports Hall Booking Portal Widget */
  // Initial Load Configuration
  if (!input) {
    data.currentUser = {
      sys_id: gs.getUserID(),
      name: gs.getUser().getDisplayName()
    };

    // 1. Fetch Sports Halls
    data.sportsHalls = [];
    var hallGr = new GlideRecord('x_2112820_sports_2_sports_hall');
    hallGr.query();
    while (hallGr.next()) {
      data.sportsHalls.push({
        sys_id: hallGr.getUniqueValue(),
        hall_name: hallGr.getValue('hall_name'),
        location: hallGr.getValue('location'),
        capacity: hallGr.getValue('capacity'),
        contact_number: hallGr.getValue('contact_number'),
        facilities: hallGr.getValue('facilities'),
        availability_status: hallGr.getValue('availability_status'),
        availability_status_label: hallGr.getDisplayValue('availability_status'),
        sport_type: hallGr.getValue('sport_type'),
        sport_type_label: hallGr.getDisplayValue('sport_type')
      });
    }
    // 2. Fetch User Dashboard Bookings
    data.myBookings = getUserDashboardBookings();
  }
  // Handle Client AJAX requests
  if (input) {
    var action = input.action;
    // A. Fetch Time Slots with booking availability for selected hall and date
    if (action === 'get_slots') {
      var sportsHallId = input.sports_hall_id;
      var bookingDate = input.booking_date; // Format YYYY-MM-DD

      data.slots = [];

      // Fetch all slots configured for this sports hall
      var slotGr = new GlideRecord('x_2112820_sports_2_time_slot');
      slotGr.addQuery('sports_hall', sportsHallId);
      slotGr.orderBy('start_time');
      slotGr.query();

      while (slotGr.next()) {
        var slotId = slotGr.getUniqueValue();
        var bookingStatus = '';
        var bookingStatusLabel = '';

        // Check if there is an active booking request for this slot on this date
        var checkGr = new GlideRecord('x_2112820_sports_2_booking');
        checkGr.addQuery('sports_hall', sportsHallId);
        checkGr.addQuery('booking_date', bookingDate);
        checkGr.addQuery('time_slot', slotId);
        // Exclude cancelled/rejected bookings from blocking slots
        checkGr.addQuery('booking_status', 'IN', 'pending,approved');
        checkGr.query();

        if (checkGr.next()) {
          bookingStatus = checkGr.getValue('booking_status');
          bookingStatusLabel = checkGr.getDisplayValue('booking_status');
        }

        data.slots.push({
          sys_id: slotId,
          slot_name: slotGr.getValue('slot_name'),
          start_time: slotGr.getDisplayValue('start_time'),
          end_time: slotGr.getDisplayValue('end_time'),
          status: slotGr.getValue('status'),
          status_label: slotGr.getDisplayValue('status'),
          booking_status: bookingStatus,
          booking_status_label: bookingStatusLabel
        });
      }
    }
    // B. Submit Reservation Request
    else if (action === 'submit_booking') {
      var sportsHallId = input.sports_hall_id;
      var bookingDate = input.booking_date;
      var timeSlotId = input.time_slot_id;
      var remarks = input.remarks;

      // 1. Double check slot availability to prevent race conditions (Duplicate Prevention)
      var checkConflict = new GlideRecord('x_2112820_sports_2_booking');
      checkConflict.addQuery('sports_hall', sportsHallId);
      checkConflict.addQuery('booking_date', bookingDate);
      checkConflict.addQuery('time_slot', timeSlotId);
      checkConflict.addQuery('booking_status', 'approved');
      checkConflict.query();

      if (checkConflict.hasNext()) {
        data.success = false;
        data.error_message = "This slot is already booked and approved. Please select another slot.";
        return;
      }

      // 2. Insert new Booking record
      var newBooking = new GlideRecord('x_2112820_sports_2_booking');
      newBooking.initialize();
      newBooking.setValue('sports_hall', sportsHallId);
      newBooking.setValue('booking_date', bookingDate);
      newBooking.setValue('time_slot', timeSlotId);
      newBooking.setValue('student', gs.getUserID());
      newBooking.setValue('remarks', remarks);
      newBooking.setValue('booking_status', 'pending'); // Starts as Pending, Flow Designer handles routing
      var newId = newBooking.insert();

      if (newId) {
        // Fetch generated Number
        var refBooking = new GlideRecord('x_2112820_sports_2_booking');
        if (refBooking.get(newId)) {
          data.success = true;
          data.booking_number = refBooking.getValue('number');
        }
      } else {
        data.success = false;
        data.error_message = "Unable to create booking record in the database.";
      }
    }
    // C. Cancel Reservation Request
    else if (action === 'cancel_booking') {
      var bookingId = input.booking_id;

      var cancelGr = new GlideRecord('x_2112820_sports_2_booking');
      if (cancelGr.get(bookingId)) {
        // Security check: ensure user is cancelling their own booking
        if (cancelGr.getValue('student') === gs.getUserID() || gs.hasRole('x_2112820_sports_2.sports_hall_booking.admin')) {
          cancelGr.setValue('booking_status', 'cancelled');
          cancelGr.update();
          data.success = true;
        } else {
          data.success = false;
          data.error_message = "Unauthorized: You do not have permission to cancel this booking.";
        }
      } else {
        data.success = false;
        data.error_message = "Booking record not found.";
      }
    }
    // D. Refresh Dashboard Bookings
    else if (action === 'get_dashboard') {
      data.myBookings = getUserDashboardBookings();
    }
  }
  // Helper function to query dashboard records
  function getUserDashboardBookings() {
    var list = [];
    var myGr = new GlideRecord('x_2112820_sports_2_booking');
    myGr.addQuery('student', gs.getUserID());
    myGr.orderByDesc('sys_created_on');
    myGr.query();

    while (myGr.next()) {
      list.push({
        sys_id: myGr.getUniqueValue(),
        number: myGr.getValue('number'),
        sports_hall_label: myGr.getDisplayValue('sports_hall'),
        booking_date: myGr.getValue('booking_date'),
        time_slot_label: myGr.getDisplayValue('time_slot'),
        booking_status: myGr.getValue('booking_status'),
        booking_status_label: myGr.getDisplayValue('booking_status'),
        remarks: myGr.getValue('remarks')
      });
    }
    return list;
  }
})();
